import React, { useState } from 'react';
import axios from 'axios';

function App() {
  const [selectedFile, setSelectedFile] = useState(null);
  const [analysisResult, setAnalysisResult] = useState(null);
  const [loading, setLoading] = useState(false);

  // Handle file input changes.
  const handleFileChange = (e) => {
    setSelectedFile(e.target.files[0]);
  };

  // Handle form submission to send file to backend.
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!selectedFile) return;
    setLoading(true);

    // Prepare form data for the POST request.
    const formData = new FormData();
    formData.append('file', selectedFile);

    try {
      // Send the file to the FastAPI backend.
      const response = await axios.post('http://127.0.0.1:8000/analyze', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      setAnalysisResult(response.data);
    } catch (error) {
      console.error("Error in Axios request:", error);

      // If the backend returns a 4xx or 5xx error, FastAPI typically includes a `detail` field.
      if (error.response && error.response.data && error.response.data.detail) {
        setAnalysisResult({ error: error.response.data.detail });
      } else {
        setAnalysisResult({ error: "Error analyzing file" });
      }
    }

    setLoading(false);
  };

  return (
    <div style={{ margin: '20px' }}>
      <h1>Malware Detection Web App</h1>
      <form onSubmit={handleSubmit}>
        <input type="file" onChange={handleFileChange} accept=".exe" />
        <button type="submit">Analyze</button>
      </form>
      {loading && <p>Analyzing...</p>}

      {analysisResult && (
        <div>
          <h2>Analysis Result</h2>
          <pre>{JSON.stringify(analysisResult, null, 2)}</pre>
        </div>
      )}
    </div>
  );
}

export default App;
